<?php $viewMode=($_GET['mode']??'')==='view'; ?><main class="content container-fluid"><div class="page-toolbar"><a class="btn btn-outline-secondary" href="<?=url('/admin/catalogos')?>">← Volver a catálogos</a><?php if($viewMode&&$record):?><a class="btn btn-brand" href="<?=url('/admin/catalogos/formulario?type='.$type.'&id='.$record['id'])?>">Editar registro</a><?php endif;?></div><section class="card panel-card form-card form-card-sm mx-auto"><div class="card-body p-4 p-lg-5"><span class="eyebrow">CATÁLOGO DEL SISTEMA</span><h2 class="mt-2 mb-1"><?=$viewMode?'Detalle':($record?'Editar':'Nuevo')?> <?=e(strtolower($label))?></h2><p class="text-secondary mb-4"><?=$viewMode?'Consulta la información del registro.':'Define el nombre que se mostrará en formularios y módulos.'?></p><?php if($viewMode):?><div class="row g-3"><div class="col-sm-6"><div class="detail-box"><span>Identificador</span><strong>#<?=$record['id']?></strong></div></div><div class="col-sm-6"><div class="detail-box"><span>Nombre</span><strong><?=e($record['name'])?></strong></div></div><?php if($type==='tabulator_subgroups'):?><div class="col-12"><div class="detail-box"><span>Grupo relacionado</span><strong>#<?=e($record['group_id'])?></strong></div></div><?php endif;?></div><?php else:?><form method="post" action="<?=url('/admin/catalogos/guardar')?>"><?=csrf_field()?><input type="hidden" name="type" value="<?=$type?>"><input type="hidden" name="id" value="<?=e($record['id']??'')?>"><div class="vstack gap-4"><div><label class="form-label">Nombre</label><input class="form-control" required name="name" value="<?=e($record['name']??'')?>" autofocus></div><?php if($type==='tabulator_subgroups'):?><div><label class="form-label">Grupo de tabuladores</label><select class="form-select" name="group_id" required><?php foreach($groups as $g):?><option value="<?=$g['id']?>" <?=($record['group_id']??null)==$g['id']?'selected':''?>><?=e($g['name'])?></option><?php endforeach;?></select></div><?php endif;?></div><div class="form-footer"><a class="btn btn-outline-secondary" href="<?=url('/admin/catalogos')?>">Cancelar</a><button class="btn btn-brand">Guardar registro</button></div></form><?php endif;?></div></section></main>
